-- Reviewed YGOPRODeck representative faces, never proof of a particular printing.
-- Source image bytes were checked on 2026-11-28. A null language denotes the
-- provider's generic card back and is deliberately excluded from display and downloads.
CREATE TABLE yugioh_provider_art (
    provider_card_id text PRIMARY KEY CHECK (provider_card_id ~ '^[1-9][0-9]{0,9}$'),
    source_url text NOT NULL UNIQUE CHECK (source_url='https://images.ygoprodeck.com/images/cards_small/'||provider_card_id||'.jpg'),
    card_url text NOT NULL CHECK (card_url LIKE 'https://ygoprodeck.com/card/%'),
    source_sha256 text NOT NULL CHECK (source_sha256 ~ '^[0-9a-f]{64}$'),
    language text CHECK (language IN ('en','ja'))
);
CREATE TABLE yugioh_provider_printing (
    legacy_key text PRIMARY KEY,
    provider_card_id text NOT NULL REFERENCES yugioh_provider_art,
    printing_number text NOT NULL,
    original_name text NOT NULL,
    CHECK (legacy_key ~ ('^catalog:YUGIOH:en:'||provider_card_id||':[0-9a-f]{24}$'))
);



-- Unlike the regional CID map, this evidence is bound to the exact provider
-- record, current source URI and edition key. User-provided sheets take priority.
CREATE VIEW catalog_ygo_provider_reference AS
SELECT c.id AS card_id, a.source_url, a.card_url, a.source_sha256, a.language
  FROM yugioh_provider_printing p
  JOIN yugioh_provider_art a USING (provider_card_id)
  JOIN card c ON c.legacy_key=p.legacy_key AND c.number=p.printing_number AND c.original_name=p.original_name
  JOIN feed_source s ON s.id=c.source_id AND s.provider='CATALOG' AND s.source_key='YUGIOH'
 WHERE c.game_code='YUGIOH' AND c.status='PUBLISHED' AND a.language IS NOT NULL
   AND c.specs->>'passcode'=a.provider_card_id AND c.specs->>'representativeArt'=a.source_url
   AND c.source_url=a.card_url
   AND NOT EXISTS (SELECT FROM card_variant v JOIN image_sheet sh ON sh.id=v.sheet_id
                    WHERE v.card_id=c.id AND NOT sh.retired);

-- V59 covers status, key, printed number and title. Revoke a representative
-- grant immediately when the source identity or its claimed image changes.
CREATE FUNCTION revoke_changed_ygo_provider_reference() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM catalog_art_card a USING catalog_art_file f
     WHERE a.card_id=OLD.id AND a.file_id=f.id
       AND starts_with(f.source_url,'https://images.ygoprodeck.com/images/cards_small/');
    RETURN NEW;
END $$;
CREATE TRIGGER ygo_provider_reference_changed AFTER UPDATE OF specs,source_id,source_url ON card
FOR EACH ROW WHEN (OLD.game_code='YUGIOH' AND
    (OLD.source_id,OLD.source_url,OLD.specs->>'representativeArt',OLD.specs->>'passcode') IS DISTINCT FROM
    (NEW.source_id,NEW.source_url,NEW.specs->>'representativeArt',NEW.specs->>'passcode'))
EXECUTE FUNCTION revoke_changed_ygo_provider_reference();

-- The ordinary specs.images language map describes editions. A vetted
-- representative is exposed only through the CARD_REFERENCE response fields.
CREATE OR REPLACE FUNCTION local_catalog_art(card_id bigint,image_url text) RETURNS text
LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT '/media/'||f.storage_key FROM catalog_art_file f JOIN catalog_art_card a ON a.file_id=f.id
     WHERE f.source_url=$2 AND a.card_id=$1 AND f.storage_key IS NOT NULL
       AND NOT starts_with(f.source_url,'https://images.ygoprodeck.com/')
$$;
